# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs, offset=-1):
    return [v + offset for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return gather(render(emit(sift(intake(raw)))))

